import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { REPOSITORY_ROOT, readCatalog } from './build-design-skill-catalog.mjs';

export { REPOSITORY_ROOT };

export const BACKGROUND_REMOVAL_SLUG = 'background-removal';
export const MIGRATION_PATH = 'supabase/migrations/20260915000001_sync_background_removal_skill.sql';

const sha256 = value => createHash('sha256').update(value).digest('hex');
const fail = message => { throw new Error(message); };

/** Load the package through the catalog validator; never read an unchecked folder directly. */
export async function readBackgroundRemovalPackage(repositoryRoot = REPOSITORY_ROOT) {
  const { catalog, rows } = await readCatalog(repositoryRoot);
  const matches = rows.filter(row => row.manifest.slug === BACKGROUND_REMOVAL_SLUG);
  if (matches.length !== 1) fail(`Expected exactly one ${BACKGROUND_REMOVAL_SLUG} package in the catalog.`);
  const row = matches[0];
  if (row.manifest.metadata.bundle !== catalog.bundle) fail('Background-removal package bundle does not match the catalog.');
  return { catalog, row };
}

/**
 * Produce an additive migration for the already-seeded system package.
 * It deliberately requires the existing row, so it preserves the skill UUID
 * and every workspace_skills enabled choice that refers to it.
 */
export function generateMigration({ catalog, row }) {
  if (row?.manifest?.slug !== BACKGROUND_REMOVAL_SLUG) fail('Unexpected skill package.');
  if (row?.manifest?.metadata?.bundle !== catalog?.bundle) fail('Package bundle does not match catalog bundle.');
  const payload = JSON.stringify({ bundle: catalog.bundle, package: row });
  const hash = sha256(payload);
  const delimiter = `$background_removal_sync_${hash.slice(0, 16)}$`;
  if (payload.includes(delimiter) || payload.includes('$background_removal_sync$')) fail('SQL dollar delimiter collision');
  return `-- Generated by scripts/build-background-removal-skill-sync.mjs; do not hand-edit.\n-- Source bundle: ${catalog.bundle}\n-- Package SHA256: ${hash}\n-- Updates only the existing system background-removal package and its reference files.\n-- No workspace installation or enabled state is read or written.\nDO $background_removal_sync$\nDECLARE\n  payload jsonb := ${delimiter}${payload}${delimiter}::jsonb;\n  entry jsonb;\n  expected_bundle text;\n  target_id uuid;\n  file_entry jsonb;\nBEGIN\n  entry := payload->'package';\n  expected_bundle := payload->>'bundle';\n  IF expected_bundle IS NULL OR entry->'manifest'->>'slug' IS DISTINCT FROM '${BACKGROUND_REMOVAL_SLUG}'\n    OR entry->'manifest'->'metadata'->>'bundle' IS DISTINCT FROM expected_bundle THEN\n    RAISE EXCEPTION 'Background-removal sync payload has an unexpected bundle or slug';\n  END IF;\n\n  -- Do not insert: a missing row means the prerequisite catalog migration was not applied.\n  SELECT s.id INTO target_id FROM public.skills AS s\n    WHERE s.slug = '${BACKGROUND_REMOVAL_SLUG}' FOR UPDATE;\n  IF target_id IS NULL THEN\n    RAISE EXCEPTION 'Background-removal system skill is missing; apply the catalog seed before this sync';\n  END IF;\n  IF EXISTS (SELECT 1 FROM public.skills AS s WHERE s.id = target_id\n      AND (s.source IS DISTINCT FROM 'system' OR s.created_by IS NOT NULL\n        OR s.metadata->>'bundle' IS DISTINCT FROM expected_bundle)) THEN\n    RAISE EXCEPTION 'Background-removal skill is not the expected system package; nothing was changed';\n  END IF;\n\n  UPDATE public.skills AS owned SET\n    name = entry->'manifest'->>'name', description = entry->'manifest'->>'description', author = 'Loomic',\n    version = entry->'manifest'->>'version', license = entry->'manifest'->>'license',\n    category = entry->'manifest'->>'category', icon_name = entry->'manifest'->>'iconName',\n    skill_content = entry->>'content', metadata = COALESCE(owned.metadata, '{}'::jsonb) || entry->'manifest'->'metadata',\n    updated_at = now()\n  WHERE owned.id = target_id AND owned.source = 'system' AND owned.created_by IS NULL;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Background-removal ownership changed concurrently; nothing was changed'; END IF;\n\n  FOR file_entry IN SELECT value FROM jsonb_array_elements(entry->'files') LOOP\n    INSERT INTO public.skill_files (skill_id, file_path, content, mime_type)\n    VALUES (target_id, file_entry->>'file_path', file_entry->>'content', file_entry->>'mime_type')\n    ON CONFLICT (skill_id, file_path) DO UPDATE SET\n      content = EXCLUDED.content, mime_type = EXCLUDED.mime_type, updated_at = now();\n  END LOOP;\n  -- Keep this package exact when a future source revision removes a reference.\n  DELETE FROM public.skill_files AS f WHERE f.skill_id = target_id AND f.file_path LIKE 'references/%'\n    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(entry->'files') AS item\n      WHERE item->>'file_path' = f.file_path);\nEND;\n$background_removal_sync$;\n`;
}

export function decodeMigrationPayload(migration) {
  const match = /payload jsonb := (\$background_removal_sync_[0-9a-f]{16}\$)([\s\S]*?)\1::jsonb;/.exec(migration);
  if (!match) fail('Missing generated background-removal sync payload');
  const payload = JSON.parse(match[2]);
  const hash = sha256(match[2]);
  if (!migration.includes(`-- Package SHA256: ${hash}\n`)) fail('Background-removal sync payload checksum mismatch');
  if (payload?.package?.manifest?.slug !== BACKGROUND_REMOVAL_SLUG) fail('Background-removal sync payload slug mismatch');
  if (payload?.package?.manifest?.metadata?.bundle !== payload?.bundle) fail('Background-removal sync payload bundle mismatch');
  return payload;
}

export async function checkBackgroundRemovalSync(repositoryRoot = REPOSITORY_ROOT) {
  const data = await readBackgroundRemovalPackage(repositoryRoot);
  const expected = generateMigration(data);
  const actual = await readFile(path.join(repositoryRoot, MIGRATION_PATH), 'utf8');
  decodeMigrationPayload(actual);
  if (actual.replace(/\r\n/g, '\n') !== expected) fail('Generated background-removal sync migration is stale; run node scripts/build-background-removal-skill-sync.mjs --write');
  return data;
}

async function main() {
  const args = process.argv.slice(2);
  if (args.length > 1 || (args.length && !['--check', '--write'].includes(args[0])))
    fail('Usage: node scripts/build-background-removal-skill-sync.mjs [--check|--write]');
  if (args[0] === '--write') {
    const data = await readBackgroundRemovalPackage();
    await writeFile(path.join(REPOSITORY_ROOT, MIGRATION_PATH), generateMigration(data), 'utf8');
    console.log('Generated additive background-removal system-skill sync migration; no database connection used.');
  } else {
    await checkBackgroundRemovalSync();
    console.log('Verified additive background-removal system-skill sync migration; no database connection used.');
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch(error => { console.error(error.message); process.exitCode = 1; });
}
